sql.where:
faculty_user_id = #{facultyUserId} and deleted_yn = 'N'
and evaluation_year = #{criteria.evaluationYear}
and academic_year = #{criteria.academicYear}
and semester = #{criteria.semester}
and achievement_status = #{criteria.achievementStatus}
and (course_code ilike concat('%', #{criteria.courseKeyword}, '%') or course_name ilike concat('%', #{criteria.courseKeyword}, '%'))
